// LeadershipStub is a recording test double of Leadership. Each field
// On<Method> configures its method. An unconfigured method records the
// call and returns the zero values of its results.
type LeadershipStub struct {
	OnTerm   *LeadershipTermStub
	OnDone   *LeadershipDoneStub
	OnResign *LeadershipResignStub

	// group contains the stub of each method.
	group  *stub.Group
	strict bool
}

// The compiler checks that LeadershipStub implements Leadership.
var _ store.Leadership = (*LeadershipStub)(nil)

// NewLeadershipStub returns a double of Leadership that reports its
// failures to tb and applies opts. The double checks the expected counts
// of calls at the end of the test. With a nil tb, the double reports
// nothing.
func NewLeadershipStub(tb assert.TB, opts ...LeadershipStubOption) *LeadershipStub {
	s := &LeadershipStub{
		OnTerm:   &LeadershipTermStub{MethodStub: stub.NewMethodStub[LeadershipTermCall](tb, "Leadership.Term")},
		OnDone:   &LeadershipDoneStub{MethodStub: stub.NewMethodStub[LeadershipDoneCall](tb, "Leadership.Done")},
		OnResign: &LeadershipResignStub{MethodStub: stub.NewMethodStub[LeadershipResignCall](tb, "Leadership.Resign")},
	}
	s.group = stub.NewGroup(
		s.OnTerm.MethodStub,
		s.OnDone.MethodStub,
		s.OnResign.MethodStub,
	)
	for _, opt := range opts {
		opt(s)
	}
	if s.strict {
		s.group.StrictAll()
	}
	s.group.Bind(tb)
	return s
}

// NewLeadershipStubDelayed returns a double whose methods sleep d on clk
// before they return. It applies opts after the clock and the latency.
func NewLeadershipStubDelayed(
	tb assert.TB,
	d time.Duration,
	clk assert.Clock,
	opts ...LeadershipStubOption,
) *LeadershipStub {
	return NewLeadershipStub(tb, append([]LeadershipStubOption{
		LeadershipStubWithClock(clk),
		LeadershipStubWithLatency(d),
	}, opts...)...)
}

// NewLeadershipStubFailing returns a double on which each call of a method
// that can fail fails with err. It applies opts after the failure.
func NewLeadershipStubFailing(tb assert.TB, err error, opts ...LeadershipStubOption) *LeadershipStub {
	return NewLeadershipStub(tb, append([]LeadershipStubOption{LeadershipStubFailing(err)}, opts...)...)
}

// ResetCalls clears the recorded calls, the counters of the faults and the
// expected counts. It keeps the functions, the fixed results and the faults.
func (s *LeadershipStub) ResetCalls() {
	s.group.Reset()
}

// invoke returns a call of the function of Func with the arguments, and nil
// where no function is set.
func (s *LeadershipTermStub) invoke() func() LeadershipTermReturn {
	if s.fn == nil {
		return nil
	}
	return func() LeadershipTermReturn {
		r0 := s.fn()
		return LeadershipTermReturn{Result: r0}
	}
}

// Term records the call. An armed fault comes first, then the function of
// Func, then the results of Returns, and then the zero values.
func (s *LeadershipStub) Term() epoch.Epoch {
	call := LeadershipTermCall{}
	r := stub.Answer(s.OnTerm.MethodStub, call, stub.Arms[LeadershipTermCall, LeadershipTermReturn]{
		Invoke:   s.OnTerm.invoke(),
		Fallback: s.OnTerm.fallback,
		Stamp: func(c LeadershipTermCall, r LeadershipTermReturn) LeadershipTermCall {
			c.Result = r.Result
			return c
		},
	})
	return r.Result
}

// invoke returns a call of the function of Func with the arguments, and nil
// where no function is set.
func (s *LeadershipDoneStub) invoke() func() LeadershipDoneReturn {
	if s.fn == nil {
		return nil
	}
	return func() LeadershipDoneReturn {
		r0 := s.fn()
		return LeadershipDoneReturn{Result: r0}
	}
}

// Done records the call. An armed fault comes first, then the function of
// Func, then the results of Returns, and then the zero values.
func (s *LeadershipStub) Done() <-chan struct{} {
	call := LeadershipDoneCall{}
	r := stub.Answer(s.OnDone.MethodStub, call, stub.Arms[LeadershipDoneCall, LeadershipDoneReturn]{
		Invoke:   s.OnDone.invoke(),
		Fallback: s.OnDone.fallback,
		Stamp: func(c LeadershipDoneCall, r LeadershipDoneReturn) LeadershipDoneCall {
			c.Result = r.Result
			return c
		},
	})
	return r.Result
}

// invoke returns a call of the function of Func with the arguments, and nil
// where no function is set.
func (s *LeadershipResignStub) invoke(ctx context.Context) func() LeadershipResignReturn {
	if s.fn == nil {
		return nil
	}
	return func() LeadershipResignReturn {
		r0 := s.fn(ctx)
		return LeadershipResignReturn{Err: r0}
	}
}

// Resign records the call. An armed fault comes first, then the function
// of Func, then the results of Returns, and then the zero values.
func (s *LeadershipStub) Resign(ctx context.Context) error {
	call := LeadershipResignCall{Ctx: ctx}
	r := stub.Answer(s.OnResign.MethodStub, call, stub.Arms[LeadershipResignCall, LeadershipResignReturn]{
		Invoke:   s.OnResign.invoke(ctx),
		Fallback: s.OnResign.fallback,
		Fault:    func(err error) LeadershipResignReturn { return LeadershipResignReturn{Err: err} },
		Stamp: func(c LeadershipResignCall, r LeadershipResignReturn) LeadershipResignCall {
			c.Err = r.Err
			return c
		},
	})
	return r.Err
}

