// Yields makes Watch return a sequence of items. The sequence stops where
// the caller breaks out of the loop.
func (s *StoreWatchStub) Yields(items ...store.Event) *StoreWatchStub {
	s.fn = func(_ context.Context, _ shard.Scope, _ shard.NamespaceIncarnation, _ epoch.Epoch, _ shard.NodeID) iter.Seq2[store.Event, error] {
		return func(yield func(store.Event, error) bool) {
			for _, v := range items {
				if !yield(v, nil) {
					return
				}
			}
		}
	}
	return s
}

// YieldsError makes Watch return a sequence of items that fails with err
// after the last item.
func (s *StoreWatchStub) YieldsError(items []store.Event, err error) *StoreWatchStub {
	s.fn = func(_ context.Context, _ shard.Scope, _ shard.NamespaceIncarnation, _ epoch.Epoch, _ shard.NodeID) iter.Seq2[store.Event, error] {
		return func(yield func(store.Event, error) bool) {
			for _, v := range items {
				if !yield(v, nil) {
					return
				}
			}
			var zero store.Event
			yield(zero, err)
		}
	}
	return s
}

