// NewStoreStub returns a double of Store that reports its failures to tb
// and applies opts. The double checks the expected counts of calls at the
// end of the test. With a nil tb, the double reports nothing.
func NewStoreStub(tb assert.TB, opts ...StoreStubOption) *StoreStub {
	s := &StoreStub{
		OnWriter:   &StoreWriterStub{MethodStub: stub.NewMethodStub[StoreWriterCall](tb, "Store.Writer")},
		OnOutcome:  &StoreOutcomeStub{MethodStub: stub.NewMethodStub[StoreOutcomeCall](tb, "Store.Outcome")},
		OnCampaign: &StoreCampaignStub{MethodStub: stub.NewMethodStub[StoreCampaignCall](tb, "Store.Campaign")},
		OnLimits:   &StoreLimitsStub{MethodStub: stub.NewMethodStub[StoreLimitsCall](tb, "Store.Limits")},
		OnFits:     &StoreFitsStub{MethodStub: stub.NewMethodStub[StoreFitsCall](tb, "Store.Fits")},
		OnClose:    &StoreCloseStub{MethodStub: stub.NewMethodStub[StoreCloseCall](tb, "Store.Close")},
		OnHead:     &StoreHeadStub{MethodStub: stub.NewMethodStub[StoreHeadCall](tb, "Store.Head")},
		OnRead:     &StoreReadStub{MethodStub: stub.NewMethodStub[StoreReadCall](tb, "Store.Read")},
		OnWatch:    &StoreWatchStub{MethodStub: stub.NewMethodStub[StoreWatchCall](tb, "Store.Watch")},
	}
	s.group = stub.NewGroup(
		s.OnWriter.MethodStub,
		s.OnOutcome.MethodStub,
		s.OnCampaign.MethodStub,
		s.OnLimits.MethodStub,
		s.OnFits.MethodStub,
		s.OnClose.MethodStub,
		s.OnHead.MethodStub,
		s.OnRead.MethodStub,
		s.OnWatch.MethodStub,
	)
	for _, opt := range opts {
		opt(s)
	}
	if s.strict {
		s.group.StrictAll()
	}
	s.group.Bind(tb)
	return s
}

// NewStoreStubDelayed returns a double whose methods sleep d on clk before
// they return. It applies opts after the clock and the latency.
func NewStoreStubDelayed(tb assert.TB, d time.Duration, clk assert.Clock, opts ...StoreStubOption) *StoreStub {
	return NewStoreStub(tb, append([]StoreStubOption{
		StoreStubWithClock(clk),
		StoreStubWithLatency(d),
	}, opts...)...)
}

// NewStoreStubFailing returns a double on which each call of a method that
